[Form]
public class METTransferOrderExtractScreenParameters extends FormRun
{
    METTransferOrderExtractScreenParameters   metTransferOrderExtractScreenParameters;

}

    public void closeOk()
    {
        // Only save the parameters when valid, so on reopen the parameters match what is displayed in the form
        metTransferOrderExtractScreenParameters.parmRoute(filterMETRoute.valueStr());
        metTransferOrderExtractScreenParameters.parmFromWarehouse(filterFromWarehouse.valueStr());
        metTransferOrderExtractScreenParameters.parmToWarehouse(filterToWarehouse.valueStr());
        metTransferOrderExtractScreenParameters.parmShippingDateConfirm(filterInventTransferShipDate.dateValue());
        metTransferOrderExtractScreenParameters.parmCategory(filterCategory.valueStr());

        metTransferOrderExtractScreenParameters.saveLastValue(formStr(METTransferOrderExtractScreen));

        if (element.args()
            &&  element.args().caller()
            &&  element.args().caller() is FormRun
            &&  formHasMethod(element.args().caller(), identifierStr(refresh)))
        {
            element.args().caller().refresh();
        }

        super();
    }

    public void init()
    {
        Object caller;
        FormRun callerForm;

        super();

        caller = this.args().caller();
        callerForm = caller as FormRun;

        if (metTransferOrderExtractScreenParameters == null)
        {
            metTransferOrderExtractScreenParameters = METTransferOrderExtractScreenParameters::construct();
            metTransferOrderExtractScreenParameters.loadLastValue(formStr(METTransferOrderExtractScreen));
        }

        filterMETRoute.text(metTransferOrderExtractScreenParameters.parmRoute());
        filterFromWarehouse.text(metTransferOrderExtractScreenParameters.parmFromWarehouse());
        filterToWarehouse.text(metTransferOrderExtractScreenParameters.parmToWarehouse());
        filterInventTransferShipDate.dateValue(metTransferOrderExtractScreenParameters.parmShippingDateConfirm());
        filterCategory.text(metTransferOrderExtractScreenParameters.parmCategory());
    }

        /// <summary>
        /// Warehouse category lookup
        /// </summary>
        public void lookup()
        {
            //Specify the name of the table the lookup should show data from.
            SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(WHSFilters), this);
            //Create a new query
            Query                   query = new Query();
            QueryBuildDataSource    queryBuildDataSource;
            QueryBuildRange         queryBuildRange;
 
            //Specify the name of the table the lookup should show data from.
            queryBuildDataSource = query.addDataSource(tableNum(WHSFilters));
            //Filter the data on the FilterTitle field on the rsmModel table.
            queryBuildRange = queryBuildDataSource.addRange(fieldNum(WHSFilters,FilterTitle));
            //Only show records where the FilterTitle field matches the value in
            //WHSFilterTitle::Code1.
            queryBuildRange.value(queryValue(WHSFilterTitle::Code1));

            //Specify which fields should be shown  in the lookup form.
            //  field returned is the first field referenced
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, FilterNum));
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, FilterTitle));
            sysTableLookup.addLookupfield(fieldNum(WHSFilters, Description));
 
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }
